  function salvaOpz() { try { localStorage.setItem('gsmash_comandi', JSON.stringify({ saltoLevetta: opz.saltoLevetta, vibra: opz.vibra, cstick: opz.cstick })); } catch (e) { } }
  // levetta destra (C-stick): centro, raggio, dito che la tiene, colpo da mandare (direzione) e se è già partito
  const CS = { x: 0, y: 0, r: 0, id: -1, dx: 0, dy: 0, fuoco: 0, fx: 0, fy: 0, partito: false };
