      if (CS.id >= 0 && !e.vivi.has(CS.id)) { CS.id = -1; CS.dx = 0; CS.dy = 0; CS.partito = false; }
      for (const id in T.btn) if (!e.vivi.has(+id)) delete T.btn[id];
