    const gp = root.GSP && root.GSP.stato();
    if (gp) {
      if (Math.hypot(gp.x, gp.y) > Math.hypot(x, y)) { x = gp.x; y = gp.y; }
      b |= gp.b;
      if (gp.cs && CS.fuoco <= 0) { CS.fuoco = 2; CS.fx = gp.cs[0]; CS.fy = gp.cs[1]; lat.inizio = performance.now(); }
    }
