    if (!opz.saltoLevetta && y > 58) { const k = 58 / y; y = 58; x = Math.round(x * Math.max(k, .9)); }
    const mag = Math.hypot(x, y);
    storia[fr & 7] = mag;
    // scatto = dal centro (sotto il 30%) al bordo (oltre l'80%) in 3 fotogrammi al massimo
    let flick = false;
    if (mag > 80) for (let k = 1; k <= 3; k++) if (storia[(fr - k) & 7] < 30) flick = true;
    if (flick) flickFr = fr;
    const tastDir = Math.max(KP.sx, KP.dx, KP.su, KP.giu);
    const attOra = !!(b & B.ATT);
