    if (T.stick >= 0) { const dx = T.x - T.ox, dy = T.y - T.oy, l = Math.hypot(dx, dy), m = Math.min(l, T.R); if (l > 0) { kx = bx + dx / l * m; ky = by + dy / l * m; } }
    c.globalAlpha = T.stick >= 0 ? .9 : .35;
