      if (ul) { c.globalCompositeOperation = 'lighter'; c.globalAlpha = .5 + Math.sin(tv * .25) * .2; c.drawImage(root.GSD.glow('#ffd23b'), b.x - r * 1.8, b.y - r * 1.8, r * 3.6, r * 3.6); c.globalCompositeOperation = 'source-over'; c.globalAlpha = .97; }
      c.fillStyle = p || ul ? COL[b.id] : 'rgba(10,8,24,.35)';
      c.strokeStyle = COL[b.id]; c.lineWidth = 3;
      c.beginPath(); c.arc(b.x, b.y + dy, r, 0, 6.283); c.fill(); c.stroke();
      c.fillStyle = p || ul ? '#0b0b14' : '#fff';
      c.textAlign = 'center'; c.textBaseline = 'middle';
      c.font = `900 ${Math.round(b.r * (b.id === 'att' ? .22 : .2))}px "Arial Black", Impact, sans-serif`;
